def forward(groups):
    dt_str = groups[0] + groups[2] + groups[4]
    dt = datetime.strptime(dt_str, '%y%m%d%H%M%S')
    return {'stored': [int(dt.timestamp() * 1000000)], 'layout': [len(groups[1]), len(groups[3])]}

def inverse(record):
    micros = int(record['stored'][0])
    dt = datetime.fromtimestamp(micros / 1000000)
    space1 = ' ' * record['layout'][0]
    space2 = ' ' * record['layout'][1]
    return dt.strftime('%y%m%d') + space1 + dt.strftime('%H%M%S') + space2
